import {features, angle} from './core.js';
let active=false,rows=[],meta=null;
const el=id=>document.getElementById(id);
const save=(name,value)=>{const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
export function mountResearch(canRecord=()=>false){
const target=el('method');const box=document.createElement('article');box.className='card';box.style='padding:24px;margin-bottom:20px';box.innerHTML=`<h3>Research capture · camera observations</h3><p>Record numerical landmarks, including tracking failures. No images or names are saved. Use anonymous participant IDs and collect only with permission.</p><div class="split"><label>Participant ID<input id="researchParticipant" value="P01" pattern="[A-Za-z0-9_-]+"></label><label>Session ID<input id="researchSession" value="S01"></label></div><div class="split"><label>Lighting<select id="researchLight"><option>normal</option><option>dim</option><option>backlit</option></select></label><label>View<select id="researchView"><option>frontal</option><option>side</option><option>occluded</option></select></label><label>Hand<select id="researchHand"><option>left</option><option>right</option></select></label></div><div class="split"><label>Task<select id="researchTask"><option>static-hold</option><option>open-close</option><option>Open palm</option><option>Fist</option><option>Pinch</option><option>Point</option><option>Unknown</option><option>calibration-open</option><option>calibration-closed</option></select></label><label>Distance (cm)<input id="researchDistance" type="number" min="10" max="200" value="50"></label></div><div class="split"><button class="secondary" id="researchStart">Start new recording</button><button class="secondary" id="researchStop">Stop</button><button class="secondary" id="researchExport">Export research JSON</button></div><p id="researchStatus" role="status">Enable the camera in Motion studio before recording. Starting a new recording replaces previous observations.</p>`;
target.insertBefore(box,target.children[1]);
el('researchStart').onclick=()=>{if(!canRecord()){el('researchStatus').textContent='Enable the camera in Motion studio first. Simulation cannot enter research recordings.';return;}const participant=el('researchParticipant').value,session=el('researchSession').value;if(!/^[\w-]{1,40}$/.test(participant)||!/^[\w-]{1,40}$/.test(session)){el('researchStatus').textContent='Use anonymous IDs containing letters, numbers, hyphens or underscores.';return;}const distance=Number(el('researchDistance').value);if(!Number.isFinite(distance)||distance<10||distance>200){el('researchStatus').textContent='Distance must be between 10 and 200 cm.';return;}meta={participant,session,lighting:el('researchLight').value,view:el('researchView').value,hand:el('researchHand').value,task:el('researchTask').value,distance_cm:distance};rows=[];active=true;el('researchStatus').textContent='Recording camera observations. Return to Motion studio to position your hand.';};
el('researchStop').onclick=stopResearch;
el('researchExport').onclick=()=>{if(!rows.length){el('researchStatus').textContent='No camera observations recorded.';return;}save('qolda-research-'+meta.participant+'-'+meta.session+'.json',{schema:'qolda-vision.capture.v1',source:'camera',clock:'host-epoch-ms at inference start; receipt alignment is not hardware synchronization',meta,rows});};
}
export function stopResearch(){active=false;if(el('researchStatus'))el('researchStatus').textContent=rows.length+' camera observations retained. Export before starting another recording.';}
export function observeCamera(result,timeMs,inferenceMs){if(!active)return;if(rows.length>=9000){stopResearch();return;}const screen=result.landmarks?.[0],world=result.worldLandmarks?.[0];const row={time_ms:timeMs,detected:!!screen,inference_ms:inferenceMs};if(screen){row.screen=screen.map(({x,y,z})=>({x,y,z}));row.world=world?.map(({x,y,z})=>({x,y,z}))??null;row.features_screen=features(screen).vector;row.features_world=world?features(world).vector:null;const lm=world??screen;row.flexion_proxy=features(lm).extension.map(x=>1-x);row.joint_internal_angles_deg=[[1,2,3],[5,6,7],[9,10,11],[13,14,15],[17,18,19]].map(([a,b,c])=>angle(lm[a],lm[b],lm[c]));}rows.push(row);if(rows.length%15===0)el('researchStatus').textContent=rows.length+' observations · '+rows.filter(x=>!x.detected).length+' missing-hand frames';}
